class_name StateMachine
extends Node

signal state_changed(prev: StringName, next: StringName)

@export var initial_state: NodePath
@onready var state: State = get_node(initial_state) if initial_state else (get_child(0) if get_child_count() > 0 else null)

var states: Dictionary = {}

func _ready() -> void:
	await owner.ready
	for child in get_children():
		if child is State:
			states[child.name] = child
			child.state_machine = self
			child.player = owner
	if state:
		state.enter()

func _unhandled_input(event: InputEvent) -> void:
	if state:
		state.handle_input(event)

func _process(delta: float) -> void:
	if state:
		state.update(delta)

func _physics_process(delta: float) -> void:
	if state:
		state.physics_update(delta)

func transition_to(target_state_name: String, msg: Dictionary = {}) -> void:
	if not states.has(target_state_name):
		return

	var prev_name = state.name if state else ""
	if state:
		state.exit()

	state = states[target_state_name]
	state.enter(msg)
	emit_signal("state_changed", StringName(prev_name), StringName(target_state_name))
EOF

cat << 'EOF' > /home/user/state_machine_player/scripts/states/IdleState.gd
class_name IdleState
extends State

func physics_update(_delta: float) -> void:
	if not player.is_on_floor():
		state_machine.transition_to("Fall")
		return

	if Input.is_action_just_pressed("ui_accept"):
		state_machine.transition_to("Jump")
		return

	if Input.is_action_just_pressed("attack"):
		state_machine.transition_to("Attack")
		return

	var direction := Input.get_axis("ui_left", "ui_right")
	if not is_zero_approx(direction):
		state_machine.transition_to("Run")
		return

	player.velocity.x = move_toward(player.velocity.x, 0, 1000 * _delta)
	player.move_and_slide()
EOF

cat << 'EOF' > /home/user/state_machine_player/scripts/states/FallState.gd
class_name FallState
extends State

var speed := 300.0

func physics_update(delta: float) -> void:
	player.velocity.y += player.gravity * delta

	var direction := Input.get_axis("ui_left", "ui_right")
	player.velocity.x = direction * speed

	player.move_and_slide()

	if player.is_on_floor():
		if is_zero_approx(direction):
			state_machine.transition_to("Idle")
		else:
			state_machine.transition_to("Run")
EOF

